mapper.update:
UPDATE b_portal_list
SET gmt_modify = now()

    , type_id = #{typeId}


    , name = #{name}


    , gender = #{gender}


    , birthday = #{birthday}


    , passport = #{passport}


    , english_score = #{englishScore}


    , completion_date = #{completionDate}


    , visa_expiration_date = #{visaExpirationDate}


    , exam_results_date = #{examResultsDate}


    , student_visa_expiration_date = #{studentVisaExpirationDate}


    , has_completion_letter = #{hasCompletionLetter}


    , json_str = #{jsonStr}


    , adviser_id = #{adviserId}


    , official_id = #{officialId}


    , mara_id = #{maraId}


    , service_order_id = #{serviceOrderId}


    , str_state = #{strState}

WHERE id = #{id};

mapper.select:
SELECT id, gmt_create AS gmtCreate, gmt_modify AS gmtModify, type_id AS typeId, name, gender, birthday, passport, english_score AS englishScore, completion_date AS completionDate, visa_expiration_date AS visaExpirationDate, exam_results_date AS examResultsDate, student_visa_expiration_date AS studentVisaExpirationDate, has_completion_letter AS hasCompletionLetter, json_str AS jsonStr, adviser_id AS adviserId, official_id AS officialId, mara_id AS maraId, service_order_id AS serviceOrderId, str_state AS strState FROM b_portal_list WHERE 1 = 1
AND type_id = #{typeId}
AND str_state = #{strState}
AND name LIKE '%${keyword}%'
ORDER BY id DESC LIMIT #{offset}, #{rows};

SELECT count(*)
FROM b_portal_list
WHERE 1 = 1

    AND type_id = #{typeId}



    AND str_state = #{strState}


    AND name LIKE '%${keyword}%'

;
